mapper.select:
SELECT  FROM requirement_doc
WHERE workspace_id = #{workspaceId}
ORDER BY updated_at DESC

SELECT req_id AS reqId, COUNT(*) AS cnt
FROM requirement_doc WHERE workspace_id = #{workspaceId}
GROUP BY req_id

mapper.update:
UPDATE task SET req_doc_id = NULL, updated_at = GREATEST(NOW(), DATE_ADD(updated_at, INTERVAL 1 SECOND))
WHERE workspace_id = #{workspaceId} AND req_doc_id = #{reqDocId}
  AND (req_id IS NULL OR req_id <> #{reqId})

mapper.sql:
l.workspace_id = #{workspaceId} AND l.demand_id = #{demandId}
AND NOT EXISTS (SELECT 1 FROM project_member pm WHERE pm.workspace_id = d.workspace_id AND pm.project_id = d.req_id AND pm.user_id = #{viewerId} AND pm.access = 'none')
AND (d.published_at IS NOT NULL OR d.owner_user_id = #{userId})

mapper.select:
SELECT dm.id AS id, dm.title AS title, dm.status AS status, dm.priority AS priority
FROM demand_doc_link l
INNER JOIN demand dm ON dm.id = l.demand_id AND dm.workspace_id = l.workspace_id
WHERE l.workspace_id = #{workspaceId} AND l.doc_id = #{docId}
ORDER BY dm.updated_at DESC, dm.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT workspace_id, demand_id, doc_id, created_by
FROM demand_doc_link
WHERE workspace_id = #{workspaceId}

mapper.delete:
DELETE FROM demand_doc_link
WHERE workspace_id = #{workspaceId}
  AND demand_id IN (SELECT id FROM demand WHERE workspace_id = #{workspaceId} AND req_id = #{reqId})
